class Employee { int id;String name,department;double baseSalary; Employee(){this(0,"",0,"");} Employee(int id,String name,double salary,String department){this.id=id;this.name=name;this.baseSalary=salary;this.department=department;} void displayEmployeeDetails(){System.out.printf("ID: %d%nName: %s%nDepartment: %s%nBase Salary: %.2f%n",id,name,department,baseSalary);} void calculateSalary(){SalaryBreakup s=new SalaryBreakup();s.computeBreakup();s.printBreakup();}void generateSlip(){System.out.println("\n--- Salary Slip ---");displayEmployeeDetails();calculateSalary();System.out.println("------------------------");} class SalaryBreakup{double hra,da,pf,tax,netPay;void computeBreakup(){hra=baseSalary*.2;da=baseSalary*.1;pf=baseSalary*.05;tax=baseSalary*.1;netPay=baseSalary+hra+da-pf-tax;}void printBreakup(){System.out.printf("HRA: %.2f%nDA: %.2f%nPF: %.2f%nTax: %.2f%nNet Pay: %.2f%n",hra,da,pf,tax,netPay);}} }
public class Constructor { public static void main(String[] args){new Employee(1,"Ravi",30000,"CSE").generateSlip();new Employee(2,"Sita",40000,"ECE").generateSlip();} }
